// waitAllDelivered collects count deliveries from every node in parallel,
// returning an error on timeout.
func waitAllDelivered(nodes []*App, count int, timeout time.Duration) error {
	deadline := time.After(timeout)
	errCh := make(chan error, len(nodes))
	var wg sync.WaitGroup
	for i, n := range nodes {
		wg.Add(1)
		go func(idx int, app *App) {
			defer wg.Done()
			for c := 0; c < count; c++ {
				select {
				case <-app.Delivered:
				case <-deadline:
					errCh <- fmt.Errorf("node %d timed out waiting for delivery %d/%d", idx+1, c+1, count)
					return
				}
			}
		}(i, n)
	}
	wg.Wait()
	close(errCh)
	for err := range errCh {
		if err != nil {
			return err
		}
	}
	return nil
}

// TestTLATraceNormal records a happy-path trace: 4 nodes, 3 proposals, no view
// change.  Traces are written even when delivery times out, so the file is
// always useful for validation.
func TestTLATraceNormal(t *testing.T) {
	t.Parallel()

	tracesDir := "/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces"
	if err := os.MkdirAll(tracesDir, 0o755); err != nil {
