282	// Deliver delivers the given proposal
283	func (a *App) Deliver(proposal types.Proposal, signatures []types.Signature) types.Reconfig {
284		a.lock.Lock()
285		defer a.lock.Unlock()
286		defer func() {
287			a.lastRecord = lastRecord{
288				proposal:   proposal,
289				signatures: signatures,
290			}
291		}()
292		record := &AppRecord{
293			Metadata: proposal.Metadata,
294			Batch:    batchFromBytes(proposal.Payload),
295		}
296		a.Node.cb.add(record)
297		a.lastDecision = &types.Decision{
298			Proposal:   proposal,
299			Signatures: signatures,
300		}
301	
302		prevSeq := a.latestMD.LatestSequence
303	
304		a.latestMD = &smartbftprotos.ViewMetadata{}
305		if err := proto.Unmarshal(proposal.Metadata, a.latestMD); err != nil {
306			panic(err)
307		}
308	
309		a.logger.Debugf("Deliver view %d last seq %d prevSeq %d", a.latestMD.ViewId, a.latestMD.LatestSequence, prevSeq)
310		if prevSeq == a.latestMD.LatestSequence {
311			a.logger.Panicf("Committed sequence %d twice", prevSeq)
312		}
313	
314		a.Delivered <- record
315	
316		for _, req := range record.Batch.Requests {
317			request := requestFromBytes(req)
318			if request.Reconfig.InLatestDecision {
319				reconfig := request.Reconfig.recconfigToUint(a.ID)
320				return types.Reconfig{InLatestDecision: true, CurrentNodes: reconfig.CurrentNodes, CurrentConfig: reconfig.CurrentConfig}
321			}
322		}
323	
324		return types.Reconfig{InLatestDecision: false}
325	}
326	
327	type committedBatches struct {
328		lock     sync.RWMutex
329		latestMD *smartbftprotos.ViewMetadata
330		records  []*AppRecord
331	}
332	
333	func (cb *committedBatches) add(record *AppRecord) {
334		cb.lock.Lock()
335		defer cb.lock.Unlock()
336	
337		md := &smartbftprotos.ViewMetadata{}
338		if err := proto.Unmarshal(record.Metadata, md); err != nil {
339			panic(err)
340		}
341	
342		if cb.latestMD != nil && cb.latestMD.ViewId > md.ViewId {
343			return
344		}
345		if cb.latestMD != nil && cb.latestMD.LatestSequence >= md.LatestSequence {
346			return
347		}
348		cb.latestMD = md
349		cb.records = append(cb.records, record)
350	}
351	
352	func (cb *committedBatches) readAll(from *smartbftprotos.ViewMetadata) []*AppRecord {
353		cb.lock.RLock()
354		defer cb.lock.RUnlock()
355	
356		var res []*AppRecord
357		for _, entry := range cb.records {
358			md := &smartbftprotos.ViewMetadata{}
359			if err := proto.Unmarshal(entry.Metadata, md); err != nil {
360				panic(err)
361			}
362			if md.ViewId < from.ViewId || md.LatestSequence <= from.LatestSequence {
363				continue
364			}
365			res = append(res, &AppRecord{
366				Metadata: entry.Metadata,
367				Batch:    entry.Batch,
368			})
369		}
370		return res
371	}
372	
373	// Request represents a client's request
374	type Request struct {
375		ClientID string
376		ID       string
377		Reconfig Reconfig
378	}
379	
380	// ToBytes returns a byte array representation of the request
381	func (txn Request) ToBytes() []byte {
382		rawTxn, err := asn1.Marshal(txn)
383		if err != nil {
384			panic(err)
385		}
386		return rawTxn
387	}
388	
389	func requestFromBytes(req []byte) *Request {
390		var r Request
391		asn1.Unmarshal(req, &r)
392		return &r
393	}
394	
395	type batch struct {
396		Requests [][]byte
397	}
398	
399	func (b batch) toBytes() []byte {
400		rawBlock, err := asn1.Marshal(b)
401		if err != nil {
402			panic(err)
403		}
404		return rawBlock
405	}
406	
407	func batchFromBytes(rawBlock []byte) *batch {
408		var block batch
409		asn1.Unmarshal(rawBlock, &block)
410		return &block
411	}
412	
413	// AppRecord represents a committed batch and metadata
414	type AppRecord struct {
415		Batch    *batch
416		Metadata []byte
417	}
418	
419	func newNode(id uint64, network *Network, testName string, testDir string, rotateLeader bool, decisionsPerLeader uint64) *App {
420		logConfig := zap.NewDevelopmentConfig()
421		logger, _ := logConfig.Build()
422		logger = logger.With(zap.String("t", testName)).With(zap.Int64("id", int64(id)))
423		sugaredLogger := logger.Sugar()
424	
425		app := &App{
426			clock:           time.NewTicker(time.Second),
427			secondClock:     time.NewTicker(time.Second),
428			ID:              id,
429			Delivered:       make(chan *AppRecord, 100),
430			logLevel:        logConfig.Level,
431			latestMD:        &smartbftprotos.ViewMetadata{},
432			lastDecision:    &types.Decision{},
433			logger:          sugaredLogger,
434			metricsProvider: &disabled.Provider{},
435		}
436	
437		config := fastConfig
438		config.SelfID = id
439		config.SyncOnStart = true
440		config.LeaderRotation = rotateLeader
441		config.DecisionsPerLeader = decisionsPerLeader
442	
443		app.Setup = func() {
444			writeAheadLog, walInitialEntries, err := wal.InitializeAndReadAll(
445				app.logger,
446				filepath.Join(testDir, fmt.Sprintf("node%d", id)),
447				&wal.Options{Metrics: wal.NewMetrics(app.metricsProvider)},
448			)
449			if err != nil {
450				sugaredLogger.Panicf("Failed to initialize WAL: %s", err)
451			}
452	
453			if app.Consensus != nil && app.Consensus.Config.DecisionsPerLeader > 0 {
454				config.DecisionsPerLeader = app.Consensus.Config.DecisionsPerLeader
455			}
456			if app.Consensus != nil && app.Consensus.Config.LeaderRotation {
457				config.LeaderRotation = true
458			}
459	
460			c := &consensus.Consensus{
461				Config:             config,
462				ViewChangerTicker:  app.secondClock.C,
463				Scheduler:          app.clock.C,
464				Logger:             app.logger,
465				Metrics:            api.NewMetrics(app.metricsProvider),
466				WAL:                writeAheadLog,
467				Metadata:           app.latestMD,
468				Verifier:           app,
469				Signer:             app,
470				MembershipNotifier: app,
471				RequestInspector:   app,
472				Assembler:          app,
473				Synchronizer:       app,
474				Application:        app,
475				WALInitialContent:  walInitialEntries,
476				LastProposal:       app.lastRecord.proposal,
477				LastSignatures:     app.lastRecord.signatures,
478			}
479			if app.heartbeatTime != nil {
480				app.clock.Stop()
481				c.Scheduler = app.heartbeatTime
482			}
483			if app.viewChangeTime != nil {
484				app.secondClock.Stop()
485				c.ViewChangerTicker = app.viewChangeTime
486			}
487			network.AddOrUpdateNode(id, c, app)
488			c.Comm = network.GetByID(id)
489			app.Consensus = c
490		}
491		app.Setup()
492		app.Node = network.GetByID(id)
493		return app
494	}
