	for i, n := range nodes {
		wg.Add(1)
		go func(idx int, app *App) {
			defer wg.Done()
			for c := 0; c < count; c++ {
				select {
				case <-app.Delivered:
				case <-deadline:
					errCh <- fmt.Errorf("node %d timed out waiting for delivery %d/%d", idx+1, c+1, count)
					return
				}
			}
		}(i, n)
	}
	wg.Wait()
	close(errCh)
	for err := range errCh {
		if err != nil {
			return err
		}
	}
	return nil
}

